/* ─────────────── KEYTU design tokens: black, dark blue and white only ─────────────── */
@theme {
  --color-black: #0B0C0E;
  --color-navy: #0F1E33;
  --color-white: #F5F6F7;
  /* Tints and shades of the dark blue: borders, muted text, mountain layers. */
  --color-navy-1: #16294A;
  --color-navy-2: #2A3D5E;
  --color-navy-3: #56657F;
  --color-navy-4: #A5AEBD;
  --color-navy-5: #DDE1E7;

  --font-display: var(--font-barlow-condensed), "Arial Narrow", sans-serif;
  --font-body: var(--font-barlow), system-ui, sans-serif;
  --font-mono: var(--font-plex-mono), ui-monospace, monospace;

  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
}

:root {
  --gutter: clamp(20px, 4vw, 64px);
  --topbar: 68px;
  --line: var(--color-navy-2);
  --muted: var(--color-navy-4);
}

/* ─────────────── Base ─────────────── */
html:has(.crn-body) {
  scroll-padding-top: calc(var(--topbar) + 36svh); /* phones: top bar + sticky K2 strip */
}

@media (min-width: 900px) {
  html:has(.crn-body) {
    scroll-padding-top: var(--topbar);
  }
}

.crn-body {
  margin: 0;
  background: var(--color-black);
  color: var(--color-white);
  font-family: var(--font-body);
  font-size: 1.0625rem;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

.crn-body ::selection {
  background: var(--color-white);
  color: var(--color-navy);
}

.crn-body :focus-visible {
  outline: 2px solid var(--color-white);
  outline-offset: 3px;
}

.crn-label {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  margin: 0;
}

.crn-display {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: clamp(3.75rem, 10vw, 10.5rem);
  line-height: 0.86;
  letter-spacing: -0.01em;
  text-transform: uppercase;
  margin: 0;
  text-wrap: balance;
}

.crn-h2 {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: clamp(2.75rem, 5.4vw, 5.5rem);
  line-height: 0.9;
  text-transform: uppercase;
  margin: 0;
  text-wrap: balance;
}

.crn-h3 {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: clamp(1.5rem, 2vw, 2rem);
  line-height: 1;
  text-transform: uppercase;
  letter-spacing: 0.01em;
  margin: 0;
}

.crn-lead {
  font-size: clamp(1.0625rem, 1.25vw, 1.25rem);
  color: var(--color-navy-5);
  max-width: 46ch;
  margin: 0;
}

/* ─────────────── Buttons: emphasis by inversion, never by hue ─────────────── */
.crn-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  height: 48px;
  padding: 0 22px;
  border: 1px solid var(--color-white);
  background: var(--color-white);
  color: var(--color-black);
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  text-decoration: none;
  cursor: pointer;
  transition:
    background-color 200ms var(--ease-out),
    color 200ms var(--ease-out),
    transform 160ms var(--ease-out);
}

.crn-btn:active {
  transform: scale(0.97);
}

.crn-btn--outline {
  background: transparent;
  color: var(--color-white);
}

@media (hover: hover) and (pointer: fine) {
  .crn-btn:hover {
    background: var(--color-navy);
    color: var(--color-white);
  }
  .crn-btn--outline:hover {
    background: var(--color-white);
    color: var(--color-black);
  }
}

/* ─────────────── Top bar ─────────────── */
.crn-topbar {
  position: fixed;
  inset: 0 0 auto 0;
  z-index: 30;
  height: var(--topbar);
  display: flex;
  align-items: center;
  gap: 32px;
  padding: 0 var(--gutter);
  background: var(--color-black);
  border-bottom: 1px solid var(--color-navy-1);
}

.crn-logo {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--color-white);
  text-decoration: none;
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 1.75rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  line-height: 1;
}

.crn-nav {
  display: none;
  gap: 28px;
  margin-left: auto;
}

.crn-nav a {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
  text-decoration: none;
  transition: color 160ms var(--ease-out);
}

.crn-nav a:hover {
  color: var(--color-white);
}

.crn-topbar .crn-btn {
  margin-left: auto;
  height: 40px;
}

@media (min-width: 1100px) {
  .crn-nav {
    display: flex;
  }
  .crn-topbar .crn-btn {
    margin-left: 0;
  }
}

/* ─────────────── Placeholders ─────────────── */
.crn-placeholder {
  display: grid;
  background:
    repeating-linear-gradient(135deg, transparent 0 14px, color-mix(in oklab, var(--color-white) 4%, transparent) 14px 15px),
    var(--color-navy-1);
  border: 1px dashed var(--color-navy-3);
}

.crn-placeholder .crn-label {
  align-self: start;
  justify-self: start;
  padding: 12px 14px;
  color: var(--color-navy-4);
}

/* ─────────────── Hero ─────────────── */
.crn-hero {
  position: relative;
  min-height: 100svh;
  display: grid;
  align-items: end;
  padding: calc(var(--topbar) + 40px) var(--gutter) 72px;
  overflow: hidden;
  isolation: isolate;
  background: linear-gradient(180deg, var(--color-black) 0%, var(--color-navy) 100%);
}

.crn-hero__image {
  position: absolute;
  inset: 0;
  z-index: -1;
}

.crn-hero__image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.crn-hero__image.crn-placeholder {
  border: 0;
}

.crn-hero::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background: linear-gradient(180deg, transparent 30%, color-mix(in oklab, var(--color-black) 85%, transparent) 100%);
}

.crn-hero__copy {
  display: grid;
  gap: 24px;
  max-width: 980px;
}

.crn-hero__copy > .crn-label {
  color: var(--color-navy-4);
}

.crn-hero__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.crn-hero__scroll {
  position: absolute;
  right: var(--gutter);
  bottom: 28px;
  color: var(--color-navy-4);
}

/* ─────────────── Ascent: pinned K2 + chapters ─────────────── */
.crn-ascent {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  background: var(--color-black);
}

.crn-stage {
  position: sticky;
  top: var(--topbar);
  z-index: 5;
  height: 36svh;
  overflow: hidden;
  background: linear-gradient(180deg, var(--color-black) 0%, var(--color-navy) 68%, var(--color-navy-1) 100%);
  border-bottom: 1px solid var(--color-navy-1);
}

.crn-k2 {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible; /* ridges and glacier run past the viewBox so "meet" never shows an edge */
}

.crn-k2__route {
  fill: none;
  stroke: var(--color-navy-4);
  stroke-width: 2;
  stroke-dasharray: 4 7;
  opacity: 0.7;
}

.crn-k2__climbed {
  fill: none;
  stroke: var(--color-white);
  stroke-width: 3;
  stroke-linecap: round;
}

.crn-k2__camp circle {
  fill: var(--color-navy);
  stroke: var(--color-navy-4);
  stroke-width: 2;
  transition: fill 300ms var(--ease-out);
}

.crn-k2__camp[data-reached] circle {
  fill: var(--color-white);
  stroke: var(--color-white);
}

.crn-k2__climber circle {
  fill: var(--color-white);
}

.crn-k2__halo {
  fill: none !important;
  stroke: var(--color-white);
  stroke-width: 1.5;
  opacity: 0.5;
}

@media (prefers-reduced-motion: no-preference) {
  .crn-k2__halo {
    transform-box: fill-box;
    transform-origin: center;
    animation: crn-halo 2.4s var(--ease-out) infinite;
  }
}

@keyframes crn-halo {
  from {
    transform: scale(0.5);
    opacity: 0.8;
  }
  to {
    transform: scale(1.6);
    opacity: 0;
  }
}

.crn-stage__coords {
  position: absolute;
  left: var(--gutter);
  top: 18px;
  color: var(--color-navy-4);
}

/* Meter + readout */
.crn-meter {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.crn-meter__scale {
  display: none;
}

.crn-readout {
  position: absolute;
  left: var(--gutter);
  bottom: 16px;
}

.crn-readout__alt {
  margin: 0;
  font-family: var(--font-display);
  font-weight: 800;
  font-size: clamp(2.5rem, 6vw, 5.75rem);
  line-height: 0.9;
  font-variant-numeric: tabular-nums;
}

.crn-readout__camp {
  margin-top: 6px;
  color: var(--color-navy-5);
}

.crn-chapters {
  min-width: 0;
}

.crn-chapter {
  min-height: 80svh;
  padding: 72px var(--gutter);
  border-top: 1px solid var(--color-navy-1);
  display: grid;
  align-content: start;
  gap: 24px;
}

.crn-chapter__alt {
  color: var(--color-navy-4);
}

@media (min-width: 900px) {
  .crn-ascent {
    grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr);
  }

  .crn-stage {
    height: calc(100svh - var(--topbar));
    border-bottom: 0;
    border-right: 1px solid var(--color-navy-1);
  }

  .crn-meter__scale {
    display: block;
    position: absolute;
    right: 36px;
    top: 15%;
    bottom: 18%;
    width: 150px;
  }

  .crn-meter__track {
    position: absolute;
    right: 0;
    top: 0;
    bottom: 0;
    width: 2px;
    background: var(--color-navy-2);
  }

  .crn-meter__fill {
    position: absolute;
    inset: 0;
    background: var(--color-white);
    transform-origin: bottom;
  }

  .crn-meter__camps {
    list-style: none;
    margin: 0;
    padding: 0;
    position: absolute;
    inset: 0;
  }

  .crn-meter__camps li {
    position: absolute;
    right: 14px;
    transform: translateY(50%);
    display: flex;
    gap: 10px;
    align-items: baseline;
    white-space: nowrap;
    font-family: var(--font-mono);
    font-size: 0.6875rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-navy-3);
    transition: color 300ms var(--ease-out);
  }

  .crn-meter__camps li::after {
    content: "";
    position: absolute;
    right: -18px;
    top: 50%;
    width: 8px;
    height: 1px;
    background: currentColor;
  }

  .crn-meter__camps li[data-state="passed"] {
    color: var(--color-navy-4);
  }

  .crn-meter__camps li[data-state="active"] {
    color: var(--color-white);
  }

  .crn-meter__alt {
    font-variant-numeric: tabular-nums;
  }

  .crn-readout {
    bottom: 36px;
  }

  .crn-chapter {
    min-height: 100svh;
    padding: 120px var(--gutter) 96px;
  }
}


/* ─────────────── Chapter content ─────────────── */
.crn-chapter__alt {
  display: flex;
  gap: 10px;
}

.crn-muted {
  color: var(--color-navy-4);
}

.crn-wide {
  display: block;
  aspect-ratio: 16 / 9;
  overflow: hidden;
}

.crn-wide img,
.crn-card__image img,
.crn-feature__image img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.crn-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1px;
  background: var(--color-navy-1);
  border: 1px solid var(--color-navy-1);
}

.crn-card {
  background: var(--color-black);
  height: 100%;
  display: flex;
  flex-direction: column;
  transition: background-color 200ms var(--ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .crn-card:hover {
    background: var(--color-navy);
  }
}

.crn-card__image {
  display: block;
  aspect-ratio: 4 / 5;
  overflow: hidden;
  border: 0;
}

.crn-card__body {
  display: grid;
  gap: 6px;
  padding: 16px;
}

.crn-card__cat,
.crn-card__meta {
  color: var(--color-navy-4);
}

.crn-feature__product {
  display: grid;
  gap: 24px;
  padding: 24px;
  border: 1px solid var(--color-navy-1);
  background: var(--color-navy);
}

.crn-feature__image {
  display: block;
  aspect-ratio: 4 / 5;
  overflow: hidden;
}

.crn-feature__info {
  display: grid;
  gap: 12px;
  align-content: start;
}

.crn-feature__info > p:not(.crn-label) {
  margin: 0;
  color: var(--color-navy-5);
}

.crn-speclist {
  margin: 8px 0 0;
  display: grid;
  border-top: 1px solid var(--color-navy-2);
}

.crn-speclist > div {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 10px 0;
  border-bottom: 1px solid var(--color-navy-2);
}

.crn-speclist dt {
  color: var(--color-navy-4);
}

.crn-speclist dd {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.875rem;
  text-align: right;
}

/* Layer diagram: three bars that pull apart with --spread (0..1); transform only */
.crn-layers {
  margin: 8px 0;
  display: grid;
  gap: 14px;
}

.crn-layers__stack {
  position: relative;
  height: 312px;
}

.crn-layers__panel {
  position: absolute;
  left: 0;
  right: 0;
  top: calc(var(--i) * 80px);
  height: 72px;
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 0 20px;
  border: 1px solid var(--color-navy-3);
  background: var(--color-black);
  color: var(--color-navy-4);
  transform: translateY(calc(var(--i) * 40px * var(--spread, 0)));
  transition:
    background-color 300ms var(--ease-out),
    color 300ms var(--ease-out),
    border-color 300ms var(--ease-out);
}

.crn-layers__panel[data-layer="0"] {
  --i: 0;
}

.crn-layers__panel[data-layer="1"] {
  --i: 1;
}

.crn-layers__panel[data-layer="2"] {
  --i: 2;
}

.crn-layers__panel[data-active] {
  background: var(--color-white);
  color: var(--color-black);
  border-color: var(--color-white);
}

.crn-layers__name {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 2.25rem;
  line-height: 1;
  text-transform: uppercase;
  min-width: 4.5ch;
}

.crn-layers__detail {
  margin-left: auto;
  text-align: right;
}

@media (min-width: 900px) {
  .crn-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .crn-feature__product {
    grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
  }

}


/* ─────────────── Showcase: colourway swap, spec sheets, fabric zoom ─────────────── */
.crn-showcase__hero {
  display: grid;
  gap: 24px;
}

.crn-showcase__side {
  display: grid;
  gap: 14px;
  align-content: start;
}

.crn-showcase__tagline {
  margin: 0;
  color: var(--color-navy-5);
}

.crn-showcase__image {
  display: block;
  aspect-ratio: 4 / 5;
  overflow: hidden;
}

.crn-showcase__image img,
.crn-swap__layer img,
.crn-zoom__image img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.crn-swap {
  display: grid;
  gap: 16px;
}

.crn-swap__image {
  position: relative;
  aspect-ratio: 4 / 5;
  overflow: hidden;
  background: var(--color-navy-1);
}

.crn-swap__layer {
  position: absolute;
  inset: 0;
}

.crn-swap__layer > * {
  width: 100%;
  height: 100%;
}

.crn-swatches {
  border: 0;
  margin: 0;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.crn-swatches legend {
  float: left;
  color: var(--color-navy-4);
}

.crn-swatches__row {
  display: flex;
  gap: 10px;
}

.crn-swatch {
  position: relative;
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  cursor: pointer;
}

.crn-swatch input {
  position: absolute;
  inset: 0;
  margin: 0;
  opacity: 0;
  cursor: pointer;
}

.crn-swatch__chip {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: 1px solid var(--color-navy-3);
  outline: 1px solid transparent;
  outline-offset: 4px;
  transition:
    outline-color 160ms var(--ease-out),
    transform 160ms var(--ease-out);
}

.crn-swatch[data-colour="black"] .crn-swatch__chip {
  background: var(--color-black);
}

.crn-swatch[data-colour="navy"] .crn-swatch__chip {
  background: var(--color-navy);
}

.crn-swatch[data-colour="white"] .crn-swatch__chip {
  background: var(--color-white);
}

.crn-swatch input:checked + .crn-swatch__chip {
  outline-color: var(--color-white);
}

.crn-swatch input:focus-visible + .crn-swatch__chip {
  outline: 2px solid var(--color-white);
}

.crn-swatch:active .crn-swatch__chip {
  transform: scale(0.94);
}

/* Gear label */
.crn-spec {
  position: relative;
  padding: 20px;
  background: var(--color-white);
  color: var(--color-black);
  outline: 1px dashed var(--color-navy-3);
  outline-offset: -8px;
}

.crn-spec__head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-bottom: 12px;
  border-bottom: 2px solid var(--color-black);
}

.crn-spec__brand {
  margin: 0;
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 1.25rem;
  line-height: 1;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.crn-spec__code {
  margin-top: 2px;
  color: var(--color-navy-3);
}

.crn-spec__name {
  margin: 12px 0 8px;
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 1.5rem;
  text-transform: uppercase;
  line-height: 1;
}

.crn-spec__rows {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.8125rem;
}

.crn-spec__rows > div {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 8px 0;
  border-bottom: 1px solid var(--color-navy-5);
}

.crn-spec__rows dt {
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--color-navy-3);
}

.crn-spec__rows dd {
  margin: 0;
  text-align: right;
  font-weight: 500;
}

.crn-spec__foot {
  margin-top: 12px;
  color: var(--color-navy-3);
  font-size: 0.625rem;
}

/* Fabric zoom */
.crn-zoom {
  margin: 0;
  display: grid;
  gap: 10px;
}

.crn-zoom__box {
  position: relative;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  cursor: zoom-in;
  touch-action: manipulation;
}

.crn-zoom__image {
  display: block;
  width: 100%;
  height: 100%;
  transition: transform 300ms var(--ease-out);
  transform-origin: var(--zx, 50%) var(--zy, 50%);
}

.crn-zoom__box[data-zoomed] .crn-zoom__image {
  transform: scale(2.5);
}

.crn-zoom__loupe {
  position: absolute;
  width: 180px;
  height: 180px;
  border-radius: 50%;
  border: 2px solid var(--color-white);
  background-repeat: no-repeat;
  pointer-events: none;
}

.crn-pair {
  display: grid;
  gap: 24px;
}

.crn-pair__item {
  display: grid;
  gap: 12px;
  align-content: start;
}

@media (min-width: 900px) {
  .crn-showcase__hero {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    align-items: start;
  }
  .crn-pair {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}


/* ─────────────── Summit: lookbook + signup ─────────────── */
.crn-iconbtn {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border: 1px solid var(--color-navy-3);
  background: transparent;
  color: var(--color-white);
  cursor: pointer;
  transition:
    background-color 160ms var(--ease-out),
    color 160ms var(--ease-out),
    transform 160ms var(--ease-out);
}

.crn-iconbtn:active {
  transform: scale(0.95);
}

@media (hover: hover) and (pointer: fine) {
  .crn-iconbtn:hover {
    background: var(--color-white);
    color: var(--color-black);
  }
}

.crn-lookbook {
  display: grid;
  gap: 14px;
  min-width: 0;
}

.crn-lookbook__bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
}

.crn-lookbook__nav {
  display: flex;
  gap: 8px;
}

.crn-lookbook__track {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: 85%;
  gap: 16px;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  scroll-snap-type: x mandatory;
  scrollbar-width: thin;
  scrollbar-color: var(--color-navy-3) transparent;
  padding-bottom: 8px;
  cursor: grab;
}

.crn-lookbook__track:active,
.crn-lookbook__track[data-dragging] {
  cursor: grabbing;
}

.crn-lookbook__track[data-dragging] {
  scroll-snap-type: none;
}

.crn-lookbook__frame {
  margin: 0;
  scroll-snap-align: start;
  display: grid;
  gap: 10px;
}

.crn-lookbook__media {
  position: relative;
  aspect-ratio: 3 / 2;
}

.crn-lookbook__image {
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;
}

.crn-lookbook__image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  pointer-events: none;
  user-select: none;
}

.crn-hotspot {
  position: absolute;
  transform: translate(-50%, -50%);
  z-index: 2;
}

.crn-hotspot__dot {
  position: relative;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 0;
  padding: 0;
  cursor: pointer;
  background: radial-gradient(circle, var(--color-white) 0 7px, color-mix(in oklab, var(--color-white) 25%, transparent) 8px 21px, transparent 22px);
}

/* The pulse lives on a ring behind the button, so the click target itself never moves. */
.crn-hotspot__dot::after {
  content: "";
  position: absolute;
  inset: 6px;
  border-radius: 50%;
  border: 1px solid var(--color-white);
  opacity: 0;
  pointer-events: none;
}

@media (prefers-reduced-motion: no-preference) {
  .crn-hotspot__dot[aria-expanded="false"]::after {
    animation: crn-beacon 2.4s var(--ease-out) infinite;
  }
}

@keyframes crn-beacon {
  from {
    transform: scale(0.6);
    opacity: 0.8;
  }
  to {
    transform: scale(1.5);
    opacity: 0;
  }
}

.crn-hotspot__card {
  position: absolute;
  left: 50%;
  bottom: calc(100% + 8px);
  transform: translateX(-50%);
  width: 220px;
  padding: 14px 40px 14px 14px;
  background: var(--color-white);
  color: var(--color-black);
  display: grid;
  gap: 6px;
  transform-origin: bottom center;
}

@media (prefers-reduced-motion: no-preference) {
  .crn-hotspot__card {
    animation: crn-pop 180ms var(--ease-out);
  }
}

@keyframes crn-pop {
  from {
    opacity: 0;
    transform: translateX(-50%) translateY(6px) scale(0.96);
  }
}

.crn-hotspot__card .crn-muted {
  color: var(--color-navy-3);
}

.crn-hotspot__close {
  position: absolute;
  top: 6px;
  right: 6px;
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border: 0;
  background: transparent;
  color: var(--color-black);
  cursor: pointer;
}

.crn-summit__signup {
  display: grid;
  gap: 20px;
  margin-top: 24px;
  padding: 28px;
  border: 1px solid var(--color-navy-2);
  background: var(--color-navy);
}

.crn-summit__signup p {
  margin: 8px 0 0;
}

.crn-signup {
  display: grid;
  gap: 10px;
}

.crn-signup .crn-label {
  color: var(--color-navy-4);
}

.crn-signup__row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.crn-signup input {
  flex: 1 1 220px;
  min-width: 0;
  height: 48px;
  padding: 0 14px;
  border: 1px solid var(--color-navy-3);
  background: var(--color-black);
  color: var(--color-white);
  font: inherit;
}

.crn-signup input::placeholder {
  color: var(--color-navy-3);
}

.crn-signup input:focus-visible {
  outline: 2px solid var(--color-white);
  outline-offset: 0;
}

.crn-signup__error {
  color: var(--color-white) !important;
}

.crn-signup--done {
  gap: 6px;
}

@media (min-width: 900px) {
  .crn-lookbook__track {
    grid-auto-columns: 78%;
  }
}

/* ─────────────── Footer ─────────────── */
.crn-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
  padding: 40px var(--gutter);
  border-top: 1px solid var(--color-navy-1);
  color: var(--color-navy-4);
}

